void ekf_update_pos_quat(const float Z[N_MEASUREMENTS_POS_QUAT], int num_iter) {
    // parameters
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POS_QUAT];
    static float H[N_MEASUREMENTS_POS_QUAT*N_STATES];
    static float HP[N_MEASUREMENTS_POS_QUAT*N_STATES];
    static float S[N_MEASUREMENTS_POS_QUAT*N_MEASUREMENTS_POS_QUAT];
    static float S_chol[N_MEASUREMENTS_POS_QUAT*N_MEASUREMENTS_POS_QUAT];
    static float S_iDiag[N_MEASUREMENTS_POS_QUAT];
    static float K[N_STATES*N_MEASUREMENTS_POS_QUAT];

    // renaming
    float *R = ekf_R_pos_quat;

    // iterated ekf

    // save prior state for IEKF iterations
    static float X_prior[N_STATES];
    for (int i = 0; i < N_STATES; i++) X_prior[i] = X[i];

    // IEKF iterations
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_pos_quat(H);

        // compute h
        ekf_h_pos_quat(h);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POS_QUAT; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POS_QUAT] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POS_QUAT] += H[i+k*N_MEASUREMENTS_POS_QUAT] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POS_QUAT; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POS_QUAT; j++) {
                S[i+j*N_MEASUREMENTS_POS_QUAT] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POS_QUAT] += H[i+k*N_MEASUREMENTS_POS_QUAT] * HP[j+k*N_MEASUREMENTS_POS_QUAT];
                }
            }
            S[i+i*N_MEASUREMENTS_POS_QUAT] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POS_QUAT);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POS_QUAT];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POS_QUAT, (HP+(i*N_MEASUREMENTS_POS_QUAT)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POS_QUAT; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // compute iterated innovation: y_iter = Z - h + H*(X - X_prior)
        float y_iter[N_MEASUREMENTS_POS_QUAT];
        for (int j = 0; j < N_MEASUREMENTS_POS_QUAT; j++) {
            float acc = Z[j] - h[j];
            for (int k = 0; k < N_STATES; k++) {
                // H is m x n, column-major: H[row + col*m]
                acc += H[j + k*N_MEASUREMENTS_POS_QUAT] * (X[k] - X_prior[k]);
            }
            y_iter[j] = acc;
        }

        // state iterate: x^{i+1} = x_prior + K * y_iter
        for (int i = 0; i < N_STATES; i++) {
            float acc = 0.f;
            for (int j = 0; j < N_MEASUREMENTS_POS_QUAT; j++) {
                acc += K[i + j*N_STATES] * y_iter[j];
            }
            X_new[i] = X_prior[i] + acc;
        }

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // --- Recompute at final state (after last iterate + normalize) ---
    ekf_H_pos_quat(H);
    ekf_h_pos_quat(h);

    // HP = H * P   (m x n), col-major
    for (int i = 0; i < N_MEASUREMENTS_POS_QUAT; i++) {
        for (int j = 0; j < N_STATES; j++) {
            float sum = 0.f;
            for (int k = 0; k < N_STATES; k++) {
                sum += H[i + k*N_MEASUREMENTS_POS_QUAT] * ekf_P_index(k, j);
            }
            HP[i + j*N_MEASUREMENTS_POS_QUAT] = sum;
        }
    }

    // S = HPH' + R
    for (int i = 0; i < N_MEASUREMENTS_POS_QUAT; i++) {
        for (int j = 0; j < N_MEASUREMENTS_POS_QUAT; j++) {
            float sum = 0.f;
            for (int k = 0; k < N_STATES; k++) {
                sum += H[i + k*N_MEASUREMENTS_POS_QUAT] * HP[j + k*N_MEASUREMENTS_POS_QUAT];
            }
            S[i + j*N_MEASUREMENTS_POS_QUAT] = sum;
        }
        S[i + i*N_MEASUREMENTS_POS_QUAT] += R[i];
    }

    // K = P H' S^{-1}  (solve via chol)
    chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POS_QUAT);
    for (int i = 0; i < N_STATES; i++) {
        float k_row[N_MEASUREMENTS_POS_QUAT];
        chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POS_QUAT, (HP + i*N_MEASUREMENTS_POS_QUAT), k_row);
        for (int j = 0; j < N_MEASUREMENTS_POS_QUAT; j++) {
            K[i + j*N_STATES] = k_row[j];
        }
    }

    // Joseph form: P+ = P - KHP - (KHP)' + K S K'
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) {
            float Pij = P[i*(i+1)/2 + j];

            float KHP_ij = 0.f, KHP_ji = 0.f;
            for (int k = 0; k < N_MEASUREMENTS_POS_QUAT; k++) {
                KHP_ij += K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POS_QUAT];
                KHP_ji += K[j + k*N_STATES] * HP[k + i*N_MEASUREMENTS_POS_QUAT];
            }

            float KSKt_ij = 0.f;
            for (int k = 0; k < N_MEASUREMENTS_POS_QUAT; k++) {
                float Skj = 0.f;
                for (int l = 0; l < N_MEASUREMENTS_POS_QUAT; l++) {
                    Skj += S[k + l*N_MEASUREMENTS_POS_QUAT] * K[j + l*N_STATES];
                }
                KSKt_ij += K[i + k*N_STATES] * Skj;
            }

            P_new[i*(i+1)/2 + j] = Pij - KHP_ij - KHP_ji + KSKt_ij;
        }
    }

    // swap P, P_new
    swap_ptr = P; P = P_new; P_new = swap_ptr;
}
