void ekf_update_points_4(const float Z[N_MEASUREMENTS_POINTS_4], const float param[12], int num_iter) {
    // parameters
    float p3d0_x = param[0];
    float p3d0_y = param[1];
    float p3d0_z = param[2];
    float p3d1_x = param[3];
    float p3d1_y = param[4];
    float p3d1_z = param[5];
    float p3d2_x = param[6];
    float p3d2_y = param[7];
    float p3d2_z = param[8];
    float p3d3_x = param[9];
    float p3d3_y = param[10];
    float p3d3_z = param[11];
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POINTS_4];
    static float H[N_MEASUREMENTS_POINTS_4*N_STATES];
    static float HP[N_MEASUREMENTS_POINTS_4*N_STATES];
    static float S[N_MEASUREMENTS_POINTS_4*N_MEASUREMENTS_POINTS_4];
    static float S_chol[N_MEASUREMENTS_POINTS_4*N_MEASUREMENTS_POINTS_4];
    static float S_iDiag[N_MEASUREMENTS_POINTS_4];
    static float K[N_STATES*N_MEASUREMENTS_POINTS_4];

    // renaming
    float *R = ekf_R_points_4;

    // iterated ekf

    // save prior state for IEKF iterations
    static float X_prior[N_STATES];
    for (int i = 0; i < N_STATES; i++) X_prior[i] = X[i];

    // IEKF iterations
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_points_4(H, param);

        // compute h
        ekf_h_points_4(h, param);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POINTS_4; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POINTS_4] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POINTS_4] += H[i+k*N_MEASUREMENTS_POINTS_4] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POINTS_4; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POINTS_4; j++) {
                S[i+j*N_MEASUREMENTS_POINTS_4] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POINTS_4] += H[i+k*N_MEASUREMENTS_POINTS_4] * HP[j+k*N_MEASUREMENTS_POINTS_4];
                }
            }
            S[i+i*N_MEASUREMENTS_POINTS_4] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_4);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POINTS_4];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_4, (HP+(i*N_MEASUREMENTS_POINTS_4)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POINTS_4; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // compute iterated innovation: y_iter = Z - h + H*(X - X_prior)
        float y_iter[N_MEASUREMENTS_POINTS_4];
        for (int j = 0; j < N_MEASUREMENTS_POINTS_4; j++) {
            float acc = Z[j] - h[j];
            for (int k = 0; k < N_STATES; k++) {
                // H is m x n, column-major: H[row + col*m]
                acc += H[j + k*N_MEASUREMENTS_POINTS_4] * (X[k] - X_prior[k]);
            }
            y_iter[j] = acc;
        }

        // state iterate: x^{i+1} = x_prior + K * y_iter
        for (int i = 0; i < N_STATES; i++) {
            float acc = 0.f;
            for (int j = 0; j < N_MEASUREMENTS_POINTS_4; j++) {
                acc += K[i + j*N_STATES] * y_iter[j];
            }
            X_new[i] = X_prior[i] + acc;
        }

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // --- Recompute at final state (after last iterate + normalize) ---
    ekf_H_points_4(H, param);
    ekf_h_points_4(h, param);

    // HP = H * P   (m x n), col-major
    for (int i = 0; i < N_MEASUREMENTS_POINTS_4; i++) {
        for (int j = 0; j < N_STATES; j++) {
            float sum = 0.f;
            for (int k = 0; k < N_STATES; k++) {
                sum += H[i + k*N_MEASUREMENTS_POINTS_4] * ekf_P_index(k, j);
            }
            HP[i + j*N_MEASUREMENTS_POINTS_4] = sum;
        }
    }

    // S = HPH' + R
    for (int i = 0; i < N_MEASUREMENTS_POINTS_4; i++) {
        for (int j = 0; j < N_MEASUREMENTS_POINTS_4; j++) {
            float sum = 0.f;
            for (int k = 0; k < N_STATES; k++) {
                sum += H[i + k*N_MEASUREMENTS_POINTS_4] * HP[j + k*N_MEASUREMENTS_POINTS_4];
            }
            S[i + j*N_MEASUREMENTS_POINTS_4] = sum;
        }
        S[i + i*N_MEASUREMENTS_POINTS_4] += R[i];
    }

    // K = P H' S^{-1}  (solve via chol)
    chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_4);
    for (int i = 0; i < N_STATES; i++) {
        float k_row[N_MEASUREMENTS_POINTS_4];
        chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_4, (HP + i*N_MEASUREMENTS_POINTS_4), k_row);
        for (int j = 0; j < N_MEASUREMENTS_POINTS_4; j++) {
            K[i + j*N_STATES] = k_row[j];
        }
    }

    // Joseph form: P+ = P - KHP - (KHP)' + K S K'
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) {
            float Pij = P[i*(i+1)/2 + j];

            float KHP_ij = 0.f, KHP_ji = 0.f;
            for (int k = 0; k < N_MEASUREMENTS_POINTS_4; k++) {
                KHP_ij += K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POINTS_4];
                KHP_ji += K[j + k*N_STATES] * HP[k + i*N_MEASUREMENTS_POINTS_4];
            }

            float KSKt_ij = 0.f;
            for (int k = 0; k < N_MEASUREMENTS_POINTS_4; k++) {
                float Skj = 0.f;
                for (int l = 0; l < N_MEASUREMENTS_POINTS_4; l++) {
                    Skj += S[k + l*N_MEASUREMENTS_POINTS_4] * K[j + l*N_STATES];
                }
                KSKt_ij += K[i + k*N_STATES] * Skj;
            }

            P_new[i*(i+1)/2 + j] = Pij - KHP_ij - KHP_ji + KSKt_ij;
        }
    }

    // swap P, P_new
    swap_ptr = P; P = P_new; P_new = swap_ptr;
}
// points_5 measurement model:
float ekf_R_points_5[N_MEASUREMENTS_POINTS_5];   // Kalman filter measurement noise covariance matrix (diagonal)

void ekf_set_R_points_5(float R_diag[N_MEASUREMENTS_POINTS_5]) {
    for (int i=0; i<N_MEASUREMENTS_POINTS_5; i++) {
        ekf_R_points_5[i] = R_diag[i];
    }
}

