void ekf_update_points_9(const float Z[N_MEASUREMENTS_POINTS_9], const float param[27], int num_iter) {
    // parameters
    float p3d0_x = param[0];
    float p3d0_y = param[1];
    float p3d0_z = param[2];
    float p3d1_x = param[3];
    float p3d1_y = param[4];
    float p3d1_z = param[5];
    float p3d2_x = param[6];
    float p3d2_y = param[7];
    float p3d2_z = param[8];
    float p3d3_x = param[9];
    float p3d3_y = param[10];
    float p3d3_z = param[11];
    float p3d4_x = param[12];
    float p3d4_y = param[13];
    float p3d4_z = param[14];
    float p3d5_x = param[15];
    float p3d5_y = param[16];
    float p3d5_z = param[17];
    float p3d6_x = param[18];
    float p3d6_y = param[19];
    float p3d6_z = param[20];
    float p3d7_x = param[21];
    float p3d7_y = param[22];
    float p3d7_z = param[23];
    float p3d8_x = param[24];
    float p3d8_y = param[25];
    float p3d8_z = param[26];
    
    // gain matrices all matrices col major
    static float h[N_MEASUREMENTS_POINTS_9];
    static float H[N_MEASUREMENTS_POINTS_9*N_STATES];
    static float HP[N_MEASUREMENTS_POINTS_9*N_STATES];
    static float S[N_MEASUREMENTS_POINTS_9*N_MEASUREMENTS_POINTS_9];
    static float S_chol[N_MEASUREMENTS_POINTS_9*N_MEASUREMENTS_POINTS_9];
    static float S_iDiag[N_MEASUREMENTS_POINTS_9];
    static float K[N_STATES*N_MEASUREMENTS_POINTS_9];

    // renaming
    float *R = ekf_R_points_9;

    // iterated ekf

    // save prior state for IEKF iterations
    static float X_prior[N_STATES];
    for (int i = 0; i < N_STATES; i++) X_prior[i] = X[i];

    // IEKF iterations
    for (int iter = 0; iter < num_iter; iter++) {
        // prepare gain calculation
        // compute H
        ekf_H_points_9(H, param);

        // compute h
        ekf_h_points_9(h, param);

        // compute HP
        for (int i = 0; i < N_MEASUREMENTS_POINTS_9; i++) {
            for (int j = 0; j < N_STATES; j++) {
                HP[i+j*N_MEASUREMENTS_POINTS_9] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    HP[i+j*N_MEASUREMENTS_POINTS_9] += H[i+k*N_MEASUREMENTS_POINTS_9] * ekf_P_index(k,j);
                }
            }
        }

        // compute S = H*P*H' + R
        for (int i = 0; i < N_MEASUREMENTS_POINTS_9; i++) {
            for (int j = 0; j < N_MEASUREMENTS_POINTS_9; j++) {
                S[i+j*N_MEASUREMENTS_POINTS_9] = 0.;
                for (int k = 0; k < N_STATES; k++) {
                    S[i+j*N_MEASUREMENTS_POINTS_9] += H[i+k*N_MEASUREMENTS_POINTS_9] * HP[j+k*N_MEASUREMENTS_POINTS_9];
                }
            }
            S[i+i*N_MEASUREMENTS_POINTS_9] += R[i];
        }

        // we have symmetric S and PHT in col major.
        // Solve K as K^T = invS * H*P, as we have columns of HP. We solve columns of K^T, which are actually rows of K
        // full state kalman update
        chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_9);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POINTS_9];
            chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_9, (HP+(i*N_MEASUREMENTS_POINTS_9)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POINTS_9; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // compute iterated innovation: y_iter = Z - h + H*(X - X_prior)
        float y_iter[N_MEASUREMENTS_POINTS_9];
        for (int j = 0; j < N_MEASUREMENTS_POINTS_9; j++) {
            float acc = Z[j] - h[j];
            for (int k = 0; k < N_STATES; k++) {
                // H is m x n, column-major: H[row + col*m]
                acc += H[j + k*N_MEASUREMENTS_POINTS_9] * (X[k] - X_prior[k]);
            }
            y_iter[j] = acc;
        }

        // state iterate: x^{i+1} = x_prior + K * y_iter
        for (int i = 0; i < N_STATES; i++) {
            float acc = 0.f;
            for (int j = 0; j < N_MEASUREMENTS_POINTS_9; j++) {
                acc += K[i + j*N_STATES] * y_iter[j];
            }
            X_new[i] = X_prior[i] + acc;
        }

        // swap X, X_new
        swap_ptr = X;
        X = X_new;
        X_new = swap_ptr;

        // normalize state
        ekf_normalize();
    }

    // --- Recompute at final state (after last iterate + normalize) ---
    ekf_H_points_9(H, param);
    ekf_h_points_9(h, param);

    // HP = H * P   (m x n), col-major
    for (int i = 0; i < N_MEASUREMENTS_POINTS_9; i++) {
        for (int j = 0; j < N_STATES; j++) {
            float sum = 0.f;
            for (int k = 0; k < N_STATES; k++) {
                sum += H[i + k*N_MEASUREMENTS_POINTS_9] * ekf_P_index(k, j);
            }
            HP[i + j*N_MEASUREMENTS_POINTS_9] = sum;
        }
    }

    // S = HPH' + R
    for (int i = 0; i < N_MEASUREMENTS_POINTS_9; i++) {
        for (int j = 0; j < N_MEASUREMENTS_POINTS_9; j++) {
            float sum = 0.f;
            for (int k = 0; k < N_STATES; k++) {
                sum += H[i + k*N_MEASUREMENTS_POINTS_9] * HP[j + k*N_MEASUREMENTS_POINTS_9];
            }
            S[i + j*N_MEASUREMENTS_POINTS_9] = sum;
        }
        S[i + i*N_MEASUREMENTS_POINTS_9] += R[i];
    }

    // K = P H' S^{-1}  (solve via chol)
    chol(S_chol, S, S_iDiag, N_MEASUREMENTS_POINTS_9);
    for (int i = 0; i < N_STATES; i++) {
        float k_row[N_MEASUREMENTS_POINTS_9];
        chol_solve(S_chol, S_iDiag, N_MEASUREMENTS_POINTS_9, (HP + i*N_MEASUREMENTS_POINTS_9), k_row);
        for (int j = 0; j < N_MEASUREMENTS_POINTS_9; j++) {
            K[i + j*N_STATES] = k_row[j];
        }
    }

    // Joseph form: P+ = P - KHP - (KHP)' + K S K'
    for (int i = 0; i < N_STATES; i++) {
        for (int j = 0; j <= i; j++) {
            float Pij = P[i*(i+1)/2 + j];

            float KHP_ij = 0.f, KHP_ji = 0.f;
            for (int k = 0; k < N_MEASUREMENTS_POINTS_9; k++) {
                KHP_ij += K[i + k*N_STATES] * HP[k + j*N_MEASUREMENTS_POINTS_9];
                KHP_ji += K[j + k*N_STATES] * HP[k + i*N_MEASUREMENTS_POINTS_9];
            }

            float KSKt_ij = 0.f;
            for (int k = 0; k < N_MEASUREMENTS_POINTS_9; k++) {
                float Skj = 0.f;
                for (int l = 0; l < N_MEASUREMENTS_POINTS_9; l++) {
                    Skj += S[k + l*N_MEASUREMENTS_POINTS_9] * K[j + l*N_STATES];
                }
                KSKt_ij += K[i + k*N_STATES] * Skj;
            }

            P_new[i*(i+1)/2 + j] = Pij - KHP_ij - KHP_ji + KSKt_ij;
        }
    }

    // swap P, P_new
    swap_ptr = P; P = P_new; P_new = swap_ptr;
}
